import{_ as e,o as a,c as s,ai as n}from"./chunks/framework.BBSijY9B.js";const m=JSON.parse('{"title":"团队模板：运营周会小组","description":"数据、简报、行动跟踪三个 Bot 配合，每周自动准备周会材料并跟进决议。","frontmatter":{"related":["/roles/managers","/templates/data-reporter"],"template":"team-ops-weekly","title":"团队模板：运营周会小组","description":"数据、简报、行动跟踪三个 Bot 配合，每周自动准备周会材料并跟进决议。","section":"templates","order":15,"role":"数据员 + 简报员 + 跟进员","type":"多 Bot 团队模板","tags":["模板","多Bot","管理","周会"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/overview","https://x.ai/news/introducing-grok-bot"],"wordCount":212,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"团队模板：运营周会小组 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"数据、简报、行动跟踪三个 Bot 配合，每周自动准备周会材料并跟进决议。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/team-ops-weekly"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-team-ops-weekly-f7e5bbf8e4.png"}],["meta",{"property":"og:image:alt","content":"团队模板：运营周会小组 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"团队模板：运营周会小组 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"数据、简报、行动跟踪三个 Bot 配合，每周自动准备周会材料并跟进决议。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-team-ops-weekly-f7e5bbf8e4.png"}],["meta",{"name":"twitter:image:alt","content":"团队模板：运营周会小组 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/team-ops-weekly"}]]},"headers":[],"relativePath":"templates/team-ops-weekly.md","filePath":"templates/team-ops-weekly.md","lastUpdated":1792485206000}'),o={name:"templates/team-ops-weekly.md"};function p(l,t,i,r,c,d){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="团队模板-运营周会小组" tabindex="-1">团队模板：运营周会小组 <a class="header-anchor" href="#团队模板-运营周会小组" aria-label="Permalink to &quot;团队模板：运营周会小组&quot;">​</a></h1><ul><li><strong>成员</strong>：数据员、简报员、跟进员（3 个 Bot）</li><li><strong>类型</strong>：多 Bot 团队模板</li><li><strong>需要的连接</strong>：网盘或数据后台、日历、邮箱；可选 Slack</li><li><strong>适合谁</strong>：每周要开运营例会、需要材料和跟进的团队负责人</li></ul><h2 id="成员入职说明" tabindex="-1">成员入职说明 <a class="header-anchor" href="#成员入职说明" aria-label="Permalink to &quot;成员入职说明&quot;">​</a></h2><p><strong>数据员</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是&quot;数据员&quot;。每周一早上从（数据来源）获取上周数据，按&quot;周报口径&quot;技能计算核心指标，</span></span>
<span class="line"><span>生成图表，存到 /workspace/周会/日期/数据.xlsx，完成后通知&quot;简报员&quot;。</span></span>
<span class="line"><span>没有新数据时直接报告，不得用旧数据。请记住。</span></span></code></pre></div><p><strong>简报员</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是&quot;简报员&quot;。根据数据员的结果和上周会议纪要，准备周会材料：</span></span>
<span class="line"><span>指标概览、异常及可能原因（标注为推测）、上周决议完成情况、本周建议议题。</span></span>
<span class="line"><span>做成 5 页以内的 PPT，存到同一目录，发给我审阅。请记住。</span></span></code></pre></div><p><strong>跟进员</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是&quot;跟进员&quot;。周会后根据我提供的纪要整理决议和待办（事项 / 负责人 / 截止日期），</span></span>
<span class="line"><span>为每位负责人起草提醒消息（草稿），每周三检查进展并汇报给我。</span></span>
<span class="line"><span>不得直接给任何人发消息。请记住。</span></span></code></pre></div><h2 id="运转方式" tabindex="-1">运转方式 <a class="header-anchor" href="#运转方式" aria-label="Permalink to &quot;运转方式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据员：每周一 8:00 例程；简报员：收到数据员通知后开工，周一 11:00 前交付；</span></span>
<span class="line"><span>跟进员：周会后由我手动启动，每周三 16:00 例程检查进展。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>会议节奏</strong>：双周会就把例程改成双周，或在例程里加&quot;如果本周没有会议则跳过&quot;。</li><li><strong>材料格式</strong>：习惯用文档而非 PPT 的，改成一页 Markdown 摘要。</li><li><strong>合并精简</strong>：团队规模小时，简报员和跟进员可以合并为一个&quot;周会助理&quot;。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>跟进员起草的提醒涉及同事时，务必由你确认后再发，避免语气或内容引起误解。</p></div>`,14)])])}const h=e(o,[["render",p]]);export{m as __pageData,h as default};
